import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        import yaml
        try:
            data = yaml.load(f, Loader=yaml.Loader)
        except Exception:
            raise ValueError("Invalid JSON format")

    for field in INPUT_JSON["required"]:
        if field not in data:
            raise ValueError("Required attributes are missing")

    for key, config in INPUT_JSON["properties"].items():
        if key in data:
            if not isinstance(data[key], config["type"]):
                raise ValueError("Types do not match")

    if "email" in data:
        if not re.match(EMAIL_REGEX, str(data["email"])):
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError("Attribute not found in JSON")

    return data[attribute]

